SERVER_PEER1_ASN[Host12_2]=65011;  SERVER_PEER2_ASN[Host12_2]=65012
SERVER_PEER1_ASN[Host12_3]=65011;  SERVER_PEER2_ASN[Host12_3]=65012
SERVER_PEER1_ASN[Host34_1]=65013;  SERVER_PEER2_ASN[Host34_1]=65014
